#pragma once

#include <string>
#include <string_view>

namespace core {

// All runtime files are resolved relative to the executable's directory, so
// the game works no matter which working directory it is launched from
// (Steam, a desktop shortcut, the IDE, ...).
//
//   <exe dir>/shaders/*.spv   compiled shaders (generated by the build)
//   <exe dir>/assets/...      copied from the project's assets/ folder
std::string basePath();
std::string shaderPath(std::string_view fileName);
std::string assetPath(std::string_view relativePath);

} // namespace core
